type TemplatePreview={id:string;title:string;description:string;category:string;icon:string;license:string;source_name:string;source_url:string;version:number;audience:string;tags_json:string;difficulty:string;setup_minutes:number;featured:number;blocks:any;database?:{title:string;view_type:string;layout_type:string;properties:Array<{id:string;name:string;type:string;options?:string[]}>;rows:Array<{title:string;status:string;customValues?:Record<string,unknown>}>;views:Array<{name:string;view_type:string}>}|null};
function PreviewBlock({node}:{node:any}){
  if(!node)return null;
  if(node.type==='text')return <>{node.text}</>;
  const children=(node.content||[]).map((child:any,index:number)=><PreviewBlock key={`${node.type}-${index}`} node={child}/>);
  if(node.type==='doc')return <div className="template-preview-prose">{children}</div>;
  if(node.type==='heading'){const level=Math.min(3,Math.max(1,Number(node.attrs?.level)||2));return level===1?<h1>{children}</h1>:level===2?<h2>{children}</h2>:<h3>{children}</h3>;}
  if(node.type==='paragraph')return <p>{children}</p>;
  if(node.type==='bulletList'||node.type==='taskList')return <ul className={node.type==='taskList'?'preview-task-list':''}>{children}</ul>;
  if(node.type==='orderedList')return <ol>{children}</ol>;
  if(node.type==='taskItem')return <li><span className="preview-checkbox">{node.attrs?.checked?'✓':'□'}</span>{children}</li>;
  if(node.type==='listItem')return <li>{children}</li>;
  if(node.type==='blockquote')return <blockquote>{children}</blockquote>;
  if(node.type==='table')return <div className="template-preview-table-wrap"><table className="template-preview-table"><tbody>{children}</tbody></table></div>;
  if(node.type==='tableRow')return <tr>{children}</tr>;
  if(node.type==='tableCell'||node.type==='tableHeader')return node.type==='tableHeader'?<th>{children}</th>:<td>{children}</td>;
  if(node.type==='horizontalRule')return <hr/>;
  if(node.type==='calloutBlock')return <aside className="template-preview-callout">{children}</aside>;
  return <>{children}</>;
}
