  return <><div className="overlay" onMouseDown={event=>event.target===event.currentTarget&&onClose()}><div className="dialog template-dialog"><div className="dialog-head"><div><span className="eyebrow">00AI NOTE · TEMPLATE CENTER</span><h2>템플릿 센터</h2><p>목적에 맞는 시작점을 고르고, 미리 확인한 뒤 내 워크스페이스에서 사용하세요.</p></div><button className="mini-icon" onClick={onClose} aria-label="템플릿 센터 닫기"><X size={18}/></button></div><div className="template-view-tabs"><button className={view==='public'?'active':''} onClick={()=>setView('public')}>전체 템플릿</button><button className={view==='mine'?'active':''} onClick={()=>void loadMine()}>내 템플릿</button>{isModerator&&<button className={view==='moderation'?'active':''} onClick={()=>void loadModeration()}>검수함</button>}</div>{view==='public'?<><div className="template-discovery"><input value={templateQuery} onChange={event=>setTemplateQuery(event.target.value)} placeholder="어떤 일을 정리하고 싶으세요? 이름·설명·태그 검색" aria-label="템플릿 검색"/><select value={templateSort} onChange={event=>setTemplateSort(event.target.value as 'popular'|'latest'|'title'|'rating')} aria-label="템플릿 정렬"><option value="popular">추천·인기순</option><option value="latest">최근 추가</option><option value="title">이름순</option><option value="rating">평점순</option></select></div><div className="template-audience-filter"><div className="template-audience-tabs" role="group" aria-label="이용 대상">{[['전체','전체'],['personal','개인'],['team','팀·조직'],['public','공공·행정']].map(([value,label])=><button key={value} className={audience===value?'active':''} onClick={()=>setAudience(value)}>{label}</button>)}</div><button className={`featured-filter ${featuredOnly?'active':''}`} onClick={()=>setFeaturedOnly(value=>!value)}><Star size={13} fill={featuredOnly?'currentColor':'none'}/> 추천 템플릿</button></div><div className="category-tabs">{all.map(name=><button key={name} className={categories===name?'active':''} onClick={()=>setCategories(name)}>{name}</button>)}</div><div className="template-result-count">{visible.length}개 템플릿</div><div className="template-grid">{visible.map(item=><article className="template-card managed-template" key={item.id}><span className="template-icon">{item.icon}</span><span className="template-meta">{item.category} · ★ {item.rating_count?item.rating_avg?.toFixed(1):'평가 없음'} ({item.rating_count||0})</span><div className="template-card-badges"><span>{item.audience==='personal'?'개인용':item.audience==='public'?'공공·행정':'팀·조직용'}</span><span>{item.difficulty||'쉬움'}</span><span>약 {item.setup_minutes||5}분</span>{item.has_database&&<span>데이터베이스 포함</span>}</div><b>{item.title}</b><span className="template-description">{item.description}</span><span className="template-credit">{item.author_name||item.source_name||'00AI'} · {item.license} · 복제 {item.copy_count||0}회</span><label className="template-rating">내 평가<select aria-label={`${item.title} 템플릿 평가`} value={item.my_rating||''} onChange={event=>event.target.value&&void rate(item,Number(event.target.value))}><option value="">평가 선택</option><option value="5">5점</option><option value="4">4점</option><option value="3">3점</option><option value="2">2점</option><option value="1">1점</option></select></label><div className="template-card-actions"><button className="secondary-btn" onClick={()=>void openPreview(item)}><FileText size={13}/> 미리보기</button><button className="primary" onClick={()=>onSelect(item.id)}><Copy size={13}/> 복제</button><button className="link-button" onClick={()=>void report(item)}>신고</button></div></article>)}</div>{visible.length===0&&<div className="empty-tree">조건에 맞는 템플릿이 없습니다. 검색어를 바꾸거나 ‘전체’로 필터를 초기화해 보세요.</div>}</>:loading?<div className="empty-tree">불러오는 중…</div>:view==='moderation'?<><h3>공개 대기</h3><div className="template-grid">{(moderation?.pending||[]).map(item=><article className="template-card managed-template" key={item.id}><span className="template-icon">{item.icon}</span><span className="template-meta">{item.category} · {item.author_name||'작성자'} · 미처리 신고 {item.open_reports||0}건</span><b>{item.title}</b><span className="template-description">{item.description}</span><div><button className="primary" onClick={()=>void moderate(`/templates/moderation/templates/${item.id}`,'approve')}>승인</button><button className="secondary-btn" onClick={()=>void moderate(`/templates/moderation/templates/${item.id}`,'reject')}>반려</button></div></article>)}</div>{!moderation?.pending.length&&<div className="empty-tree">검토 대기 템플릿이 없습니다.</div>}<h3>미처리 신고</h3><div className="template-version-list">{(moderation?.reports||[]).map(report=><article key={report.id}><span><b>{report.template_title}</b> · {report.reporter_name}: {report.reason}</span><button className="secondary-btn" onClick={()=>void moderate(`/templates/moderation/reports/${report.id}`,'dismiss')}>기각</button><button className="secondary-btn" onClick={()=>void moderate(`/templates/moderation/reports/${report.id}`,'hide')}>공개 중단</button></article>)}{!moderation?.reports.length&&<div className="empty-tree">미처리 신고가 없습니다.</div>}</div></>:<><div className="template-grid">{mine.map(item=><article className="template-card managed-template" key={item.id}><span className="template-icon">{item.icon}</span><span className="template-meta">{item.category} · {item.review_status==='pending'?'검토 대기':item.visibility==='public'?'공개':'비공개'}</span><b>{item.title}</b><span className="template-description">{item.description}</span><span className="template-credit">{item.license} · 복제 {item.copy_count||0}회</span><div><button className="secondary-btn" onClick={()=>void toggleVisibility(item)}>{item.visibility==='public'?'비공개로 전환':'공개로 게시'}</button><button className="link-button" onClick={()=>void showVersions(item)}>버전 이력</button><button className="link-button" onClick={()=>void remove(item)}>삭제</button></div></article>)}{mine.length===0&&<div className="empty-tree">아직 등록한 템플릿이 없습니다. 문서 하단의 ‘템플릿 등록’에서 시작해 보세요.</div>}</div>{historyFor&&<section className="template-version-list"><div><b>버전 이력</b><button className="link-button" onClick={()=>setHistoryFor(null)}>닫기</button></div>{versions.map(version=><article key={version.id}><span>v{version.version} · {version.title} · {new Date(version.created_at).toLocaleString('ko-KR')}</span><button className="secondary-btn" disabled={mine.find(item=>item.id===historyFor)?.version===version.version} onClick={()=>{const item=mine.find(row=>row.id===historyFor);if(item)void restoreVersion(item,version.id);}}>복원</button></article>)}</section>}</>}<div className="dialog-note"><ShieldCheckIcon/> 공개 템플릿은 출처와 이용 조건을 표시합니다. 복제된 데이터베이스 구조·보기·샘플 항목은 독립된 사본으로 저장됩니다.</div></div></div>{previewLoading&&<div className="overlay template-preview-overlay"><div className="dialog template-preview-dialog"><div className="members-loading">템플릿 미리보기를 불러오는 중…</div></div></div>}{previewError&&<div className="overlay template-preview-overlay" onMouseDown={event=>event.target===event.currentTarget&&setPreviewError('')}><div className="dialog template-preview-dialog"><div className="dialog-head"><div><span className="eyebrow">TEMPLATE PREVIEW</span><h2>미리보기를 열지 못했습니다</h2><p>{previewError}</p></div><button className="mini-icon" onClick={()=>setPreviewError('')} aria-label="닫기"><X size={18}/></button></div></div></div>}{preview&&<TemplatePreviewDialog item={preview} onClose={()=>setPreview(null)} onSelect={id=>{setPreview(null);onSelect(id);}}/>}</>;
